// Main computational kernel
// A: i x j (row-major, j inner)
// s: j
// q: i
// p: j
// r: i
//
// Original mathematical form:
//
//   s[j] = 0
//   for i:
//     q[i] = 0
//     for j:
//       s[j] += r[i] * A[i,j]
//       q[i] += A[i,j] * p[j]
//
// Optimizations applied:
//
//   * 2D blocking (tiling) of (i,j) using noarr::into_blocks_dynamic:
//       - tile_i: tile size in i (rows)
//       - tile_j: tile size in j (cols)
//     This improves cache locality for A, p, s and q.
//
//   * Loop order: I, i, J, j (I/J are tile indices, i/j intra-tile):
//       for I (tiles of i)            // outermost
//         for i in tile I             // rows within the tile
//           ri = r[i]; qi = 0         // hoist r[i] and q[i] accumulator
//           for J (tiles of j)
//             for j in tile J
//               s[j] += ri * A[i,j]
//               qi   += A[i,j] * p[j]
//           q[i] = qi
//     This preserves the original dependency order:
//       - For each fixed i, q[i] still accumulates j in increasing order.
//       - For each fixed j, s[j] still accumulates i in increasing order.
//
//   * Registerization of q[i]:
//       - Use a scalar accumulator qi per i, written back once per row,
//         reducing repeated loads/stores of q[i] inside the inner loops.
//
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	// Tunable tile sizes; chosen as reasonable defaults for modern CPUs.
	// They do not need to divide N or M exactly; into_blocks_dynamic
	// handles partial tiles safely.
	constexpr std::size_t tile_i = 64;
	constexpr std::size_t tile_j = 256;

	#pragma scop
	// s[j] = 0 for all j
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// 2D blocking of (i, j) using into_blocks_dynamic:
	//   - split 'i' into (I, i) with guard dimension 'x'
	//   - split 'j' into (J, j) with guard dimension 'y'
	//
	// The guard dimensions ensure that when N or M is not an exact multiple
	// of tile_i or tile_j, the last, partial tiles are handled correctly
	// without any explicit bounds checks in the kernel.
	auto blocking =
		into_blocks_dynamic<'i', 'I', 'i', 'x'>(tile_i) ^
		into_blocks_dynamic<'j', 'J', 'j', 'y'>(tile_j);

	// Traverser over all structures with blocked order applied.
	// The states passed to the lambdas still use the original dimension
	// names ('i', 'j'); the block indices ('I', 'J') are only visible to
	// for_dims and guide the traversal order.
	traverser(A, s, q, p, r)
		.order(blocking)
		// Outer loop over i-tiles (I)
		.template for_dims<'I'>([&](auto trav_I) {
			// Loop over rows i inside the current i-tile
			trav_I.template for_dims<'i'>([&](auto trav_i) {
				// State with current i fixed (only 'i' is present here)
				auto i_state = trav_i.state();

				// Hoist r[i] and initialize a register accumulator for q[i]
				num_t ri = r[i_state];
				num_t qi = SCALAR_VAL(0.0);

				// Loop over j-tiles (J) for this fixed i
				trav_i.template for_dims<'J'>([&](auto trav_J) {
					// Within a j-tile, iterate over all valid (i,j) pairs.
					// The guard dimension from into_blocks_dynamic ensures
					// that out-of-range (i,j) combinations are not visited.
					trav_J.for_each([&](auto state) {
						// state logically has indices 'i' and 'j'
						num_t a_ij = A[state];

						// s[j] += r[i] * A[i,j];
						s[state] += ri * a_ij;

						// Accumulate q[i] in a register:
						//   q[i] += A[i,j] * p[j];
						qi += a_ij * p[state];
					});
				});

				// Write back q[i] once per row, after processing all j-tiles.
				q[i_state] = qi;
			});
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Retrieve problem size
	std::size_t n = N; // length in 'i'
	std::size_t m = M; // length in 'j'

