// A: i x j
// s: j
// q: i
// p: j
// r: i
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	// ------------------------------------------------------------------
	// Tiling parameters
	//
	// TI: tile size in the row dimension 'i'
	// TJ: tile size in the column dimension 'j'
	//
	// They are chosen conservatively; the exact values can be tuned
	// per target machine. Using into_blocks_dynamic makes this correct
	// for arbitrary problem sizes N and M (no need for N, M to be
	// multiples of TI/TJ).
	// ------------------------------------------------------------------
	constexpr std::size_t TI = 64;
	constexpr std::size_t TJ = 256;

	// ------------------------------------------------------------------
	// Create a tiled view of A:
	//
	//   - First split 'i' into blocks:
	//       'I' : block index  (tile of rows)
	//       'i' : index within the tile
	//       'g' : guard dimension (length 1 if this (I,i) is inside [0,N),
	//                              length 0 otherwise)
	//
	//   - Then split 'j' into blocks:
	//       'J' : block index  (tile of columns)
	//       'j' : index within the tile
	//       'h' : guard dimension (length 1 if this (J,j) is inside [0,M),
	//                              length 0 otherwise)
	//
	// Only A is tiled; the 1D vectors keep their simple layouts.
	// The traverser can still combine them because dimensions that
	// are absent in a particular structure are simply ignored there.
	// ------------------------------------------------------------------
	auto A_tiled =
		A
		^ noarr::into_blocks_dynamic<'i', 'I', 'i', 'g'>(TI)
		^ noarr::into_blocks_dynamic<'j', 'J', 'j', 'h'>(TJ);

	#pragma scop
	// --------------------------------------------------------------
	// s[j] = 0 for all j
	// --------------------------------------------------------------
	traverser(s).for_each([=](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

