	// Fused BiCG kernel with 2D blocking on A and register
	// accumulators for q[i].
	//
	// Mathematical goal (unchanged):
	//   s[j] = sum_i r[i] * A[i,j]
	//   q[i] = sum_j A[i,j] * p[j]
	//
	// We traverse tiles of A in (I,J) order:
	//   for each tile I of rows:
	//     for each (valid) row i in that tile:
	//       ri = r[i];           // hoisted scalar
	//       qi = 0;              // accumulator for q[i]
	//       for each tile J of columns:
	//         for each (valid) column j in that tile:
	//           a = A[i,j];
	//           s[j] += ri * a;
	//           qi   += a * p[j];
	//       q[i] = qi;
	//
	// The guard dimensions 'g' and 'h' created by into_blocks_dynamic
	// guarantee that, even when N or M is not a multiple of TI/TJ,
	// only valid (i,j) pairs are visited by the traverser (tiles that
	// go out of bounds just have zero length in the guard dimension
	// and are therefore skipped).
	// --------------------------------------------------------------
	traverser(A_tiled, s, q, p, r).template for_dims<'I'>([=](auto trav_I) {
		// Traverse all valid rows inside the current I-tile.
		// Dimension 'g' is the presence-guard; including it in
		// for_dims ensures that rows beyond N in the last tile
		// are automatically skipped.
		trav_I.template for_dims<'i', 'g'>([=](auto trav_i) {
			// State for the current global row i (plus tile info).
			auto istate = trav_i.state();

			// r[i] hoisted out of the inner j-loop
			num_t ri = r[istate];

			// Accumulator for q[i] in a scalar register
			num_t qi = SCALAR_VAL(0.0);

			// Walk tiles of columns J for this row
			trav_i.template for_dims<'J'>([=](auto trav_J) {
				// For each (valid) (j, h) inside this column tile.
				// The guard dimension 'h' again ensures that in the
				// last tile we do not access j >= M.
				trav_J.for_each([=](auto state) {
					// state carries indices {I, i, g, J, j, h};
					// each bag only uses the dimensions it has:
					//   - A_tiled uses (I,i,g,J,j,h),
					//   - s, p use 'j',
					//   - q, r use 'i'.
					num_t a = A_tiled[state]; // A[i,j] in tiled view

					// s[j] += r[i] * A[i,j];
					s[state] += ri * a;

					// q[i] += A[i,j] * p[j];
					qi += a * p[state];
				});
			});

			// Single write to q[i] after accumulating over all j.
			q[istate] = qi;
		});
	});
	#pragma endscop
}

