constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j (row-major: j is the inner/fast dimension)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// 1D vectors
	DEFINE_PROTO_STRUCT(s_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(q_layout, i_vec); // length N, index 'i'
	DEFINE_PROTO_STRUCT(p_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(r_layout, i_vec); // length N, index 'i'
} tuning;

// Array initialization
// A: i x j
// r: i
// p: j
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// p[j] = (j % m) / m;
	traverser(p).for_each([&](auto state) {
		auto j = get_index<'j'>(state);
		auto m = p | get_length<'j'>();
		p[state] = (num_t)(j % m) / (num_t)m;
	});

	// r[i] = (i % n) / n;
	traverser(r).for_each([&](auto state) {
		auto i = get_index<'i'>(state);
		auto n = r | get_length<'i'>();
		r[state] = (num_t)(i % n) / (num_t)n;
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		auto n = A | get_length<'i'>();
		A[state] = (num_t)(i * (j + 1) % n) / (num_t)n;
	});
}

// Main computational kernel
// A: i x j
// s: j
// q: i
// p: j
// r: i
//
// Optimizations compared to the baseline kernel:
//
// 1) Keep A row-major (j fastest), but introduce a *tiled view* of the j
//    dimension using noarr::into_blocks_static. This yields better cache
//    locality for A, p, and s while preserving the original layout.
//
//    We split 'j' into:
//      - 'b' : body (0) vs border (1) tiles (tuple-like, length 2),
//      - 'J' : tile index,
//      - 'j' : index within a tile.
//
//    Memory layout does not change; only the traversal order and indexing
//    are modified.
//
// 2) For each row i, we hoist r[i] into a scalar 'ri' and accumulate q[i]
//    into a scalar 'qi'. This keeps r[i] and q[i] in registers across the
//    inner tile/j loops and writes q[i] back exactly once per row, reducing
//    memory traffic and making vectorization easier.
//
// 3) We still fuse the two BiCG reductions (s = A^T * r, q = A * p) so that
//    each A[i,j] is loaded once and reused for both updates.
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	// Tile size along the fast 'j' dimension.
	// This is a compile-time constant chosen for a reasonable cache line
	// / SIMD-friendly block; it can be retuned per architecture.
	constexpr std::size_t tile_j = 256;

	// Build a proto-structure that splits dimension 'j' into:
	//   - 'b' (body/border selector, tuple-like dim of length 2),
	//   - 'J' (block index),
	//   - 'j' (index inside a block).
	//
	// into_blocks_static guarantees that all (b, J, j) combinations
	// correspond to *valid* original j-indices; there are no "invalid"
	// iterations, even when M is not a multiple of tile_j. The memory
	// layout of all bags remains unchanged.
	auto block_j_proto =
		noarr::into_blocks_static<'j', 'b', 'J', 'j'>(noarr::lit<tile_j>);

	// Create blocked views for the data that depend on dimension 'j'.
	// Bags share the same underlying data; only their structures (views)
	// change.
	auto A_blocked = A ^ block_j_proto;
	auto s_blocked = s ^ block_j_proto;
	auto p_blocked = p ^ block_j_proto;
	// q and r do not depend on 'j', so we keep their original layouts.

	#pragma scop
	// ------------------------------------------------------------------
	// 1) Initialize s[j] = 0 for all j.
	// ------------------------------------------------------------------
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// ------------------------------------------------------------------
	// 2) Main BiCG kernel with j-tiling and register accumulators.
	//
	//    For each row i:
	//      ri := r[i]                  (hoisted)
	//      qi := 0                     (accumulator for q[i])
	//      for all (tiles J, positions j in tile):
	//        a_ij := A[i, j]
	//        s[j]  += ri * a_ij
	//        qi    += a_ij * p[j]
	//      q[i] = qi
	//
	//    Traverser over (A_blocked, s_blocked, p_blocked, q, r) ensures
	//    a fused, cache-friendly traversal:
	//      - outer loop over 'i' (rows),
	//      - inner loops over the blocked 'j' structure ('b', 'J', 'j'),
	//    while states still index A/s/p consistently and q/r only use 'i'.
	// ------------------------------------------------------------------
	traverser(A_blocked, s_blocked, p_blocked, q, r)
		.template for_dims<'i'>([&](auto trav_i) {
			// trav_i has the current 'i' fixed; remaining dimensions
			// describe the j-tiling ('b', 'J', 'j') for this row.
			auto state_i = trav_i.state(); // contains only 'i'

			// Hoist r[i] and q[i] into registers.
			const num_t ri = r[state_i];
			num_t qi = SCALAR_VAL(0.0);

			// Iterate over all tiles and intra-tile positions in 'j'
			// for the current row i. The order is:
			//   for b in {body,border}
			//     for J in tiles of size tile_j
			//       for j in that tile
			//         ...
			// but all of this is expressed through the traverser.
			trav_i.for_each([&](auto state) {
				// 'state' contains at least ('i', 'b', 'J', 'j').
				// - A_blocked/s_blocked/p_blocked use all of them.
				// - q and r only use 'i' and ignore the others.

				const num_t a_ij = A_blocked[state];

				// s[j] += r[i] * A[i,j];
				s_blocked[state] += ri * a_ij;

				// q[i] += A[i,j] * p[j];
				qi += a_ij * p_blocked[state];
			});

			// Write q[i] back once per row.
			q[state_i] = qi;
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Retrieve problem size
	std::size_t n = N; // length in 'i'
	std::size_t m = M; // length in 'j'

	// Common length proto-structure
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(m);

	// Allocate bags with chosen layouts
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto s = noarr::bag(noarr::scalar<num_t>() ^ tuning.s_layout ^ set_lengths);
	auto q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);
	auto p = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto r = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);

	// Initialize arrays
	init_array(A.get_ref(), r.get_ref(), p.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_bicg(A.get_ref(), s.get_ref(), q.get_ref(), p.get_ref(), r.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print live-out data to prevent dead-code elimination
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, s.get_ref());
		noarr::serialize_data(std::cerr, q.get_ref());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
